content:
:root {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #f4f6f9;
  color: #333;
  line-height: 1.5;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #f4f6f9;
  color: #333;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  text-align: center;
  margin-bottom: 8px;
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: #1e293b;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 14px;
  color: #64748b;
}

.chart-card {
  background: #ffffff;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: #334155;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  background: #f8fafc;
  padding: 12px 16px;
  border-radius: 8px;
  border: 1px solid #e2e8f0;
}

.store-toggle {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
}

.checkbox-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background-color 0.2s;
}

.checkbox-label:hover {
  background-color: #e2e8f0;
}

.checkbox-label input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: #3b82f6;
}

@media (max-width: 600px) {
  .app-container {
    padding: 16px 8px;
  }

  .chart-card {
    padding: 16px 12px;
  }

  .controls {
    flex-direction: column;
    align-items: flex-start;
  }
}

export interface StoreData {
  month: string;
  渋谷店: number;
  新宿店: number;
  池袋店: number;
}

import { useState } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { StoreData } from './types';
import './index.css';

const initialData: StoreData[] = [
  { month: '1月', 渋谷店: 4200, 新宿店: 5100, 池袋店: 3800 },
  { month: '2月', 渋谷店: 3900, 新宿店: 4800, 池袋店: 3600 },
  { month: '3月', 渋谷店: 4800, 新宿店: 5900, 池袋店: 4200 },
  { month: '4月', 渋谷店: 4600, 新宿店: 5600, 池袋店: 4000 },
  { month: '5月', 渋谷店: 5100, 新宿店: 6200, 池袋店: 4500 },
  { month: '6月', 渋谷店: 4900, 新宿店: 6000, 池袋店: 4300 },
  { month: '7月', 渋谷店: 5500, 新宿店: 6800, 池袋店: 4900 },
  { month: '8月', 渋谷店: 5800, 新宿店: 7100, 池袋店: 5200 },
  { month: '9月', 渋谷店: 5200, 新宿店: 6400, 池袋店: 4600 },
  { month: '10月', 渋谷店: 4900, 新宿店: 6000, 池袋店: 4400 },
  { month: '11月', 渋谷店: 5300, 新宿店: 6500, 池袋店: 4700 },
  { month: '12月', 渋谷店: 6100, 新宿店: 7500, 池袋店: 5500 },
];

export default function App() {
  const [visibleStores, setVisibleStores] = useState({
    渋谷店: true,
    新宿店: true,
    池袋店: true,
  });

  const handleToggle = (storeName: keyof typeof visibleStores) => {
    setVisibleStores((prev) => ({
      ...prev,
      [storeName]: !prev[storeName],
    }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">月別店舗来客数比較</h1>
        <p className="subtitle">各店舗の年間を通じた来客数の推移を確認できます</p>
      </header>

      <main>
        <div className="chart-card">
          <h2 className="chart-title">2023年度 来客数推移（人）</h2>

          <div className="controls">
            <div className="store-toggle">
              <label className="checkbox-label" style={{ color: '#3b82f6' }}>
                <input
                  type="checkbox"
                  checked={visibleStores.渋谷店}
                  onChange={() => handleToggle('渋谷店')}
                />
                渋谷店
              </label>
              <label className="checkbox-label" style={{ color: '#10b981' }}>
                <input
                  type="checkbox"
                  checked={visibleStores.新宿店}
                  onChange={() => handleToggle('新宿店')}
                />
                新宿店
              </label>
              <label className="checkbox-label" style={{ color: '#f59e0b' }}>
                <input
                  type="checkbox"
                  checked={visibleStores.池袋店}
                  onChange={() => handleToggle('池袋店')}
                />
                池袋店
              </label>
            </div>
          </div>

          <div style={{ width: '100%', height: 400 }}>
            <ResponsiveContainer>
              <LineChart
                data={initialData}
                margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="month" stroke="#64748b" />
                <YAxis stroke="#64748b" unit="人" />
                <Tooltip
                  contentStyle={{
                    backgroundColor: '#ffffff',
                    borderRadius: '8px',
                    border: '1px solid #e2e8f0',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  }}
                />
                <Legend />
                {visibleStores.渋谷店 && (
                  <Line
                    type="monotone"
                    dataKey="渋谷店"
                    stroke="#3b82f6"
                    strokeWidth={3}
                    activeDot={{ r: 8 }}
                  />
                )}
                {visibleStores.新宿店 && (
                  <Line
                    type="monotone"
                    dataKey="新宿店"
                    stroke="#10b981"
                    strokeWidth={3}
                    activeDot={{ r: 8 }}
                  />
                )}
                {visibleStores.池袋店 && (
                  <Line
                    type="monotone"
                    dataKey="池袋店"
                    stroke="#f59e0b"
                    strokeWidth={3}
                    activeDot={{ r: 8 }}
                  />
                )}
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </main>
    </div>
  );
}
